import{_ as t,o as a,c as s,a3 as d}from"./chunks/framework.B0LNVsFV.js";const p=JSON.parse('{"title":"11. Claude Code setup","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/11-claude-code-setup.md","filePath":"chapters/11-claude-code-setup.md"}'),o={name:"chapters/11-claude-code-setup.md"};function r(i,e,n,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[d('<h1 id="_11-claude-code-setup" tabindex="-1">11. Claude Code setup <a class="header-anchor" href="#_11-claude-code-setup" aria-label="Permalink to &quot;11. Claude Code setup&quot;">​</a></h1><h2 id="read" tabindex="-1">Read <a class="header-anchor" href="#read" aria-label="Permalink to &quot;Read&quot;">​</a></h2><ul><li><a href="https://angular.dev/ai/agent-skills" target="_blank" rel="noreferrer">Angular Agent Skills</a></li><li><a href="https://angular.dev/ai/mcp" target="_blank" rel="noreferrer">Angular MCP</a></li><li><a href="https://github.com/ChromeDevTools/chrome-devtools-mcp" target="_blank" rel="noreferrer">Chrome DevTools</a></li><li>Contact training supervisor for materials regarding AI</li></ul><h2 id="practice" tabindex="-1">Practice <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;Practice&quot;">​</a></h2><ol><li>Install Claude Code and start it in the <code>contract-mgmt-ui</code> folder:</li></ol><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>claude</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol start="2"><li>Create the project memory with <code>/init</code>, then edit the result. <code>CLAUDE.md</code> is committed and shared with the team:</li></ol><table tabindex="0"><thead><tr><th>What</th><th>Business description</th></tr></thead><tbody><tr><td>Overview</td><td>What the app is and which BFF it talks to</td></tr><tr><td>Structure</td><td>The app, where features, services, store and models live</td></tr><tr><td>Technical rules</td><td>The rules of the training README: standalone, OnPush, signals, services for HTTP, i18n for every text, ng-aquila, NgRx only for beneficiaries and insured objects</td></tr><tr><td>Models</td><td>Models are generated from the Swagger file; never edited by hand</td></tr><tr><td>Quality</td><td>ESLint, Prettier, tests for every change, Conventional Commits, no skipped hooks</td></tr><tr><td>Boundaries</td><td>Authentication code (config, auth service, interceptor, guards, directive, header, login page) stays generic and knows nothing about contracts, because it moves into a library in the last chapter</td></tr></tbody></table><ol start="3"><li>Create <code>.claude/settings.json</code> (committed) with the shared project settings:</li></ol><table tabindex="0"><thead><tr><th>What</th><th>Business description</th></tr></thead><tbody><tr><td>Allowed commands</td><td>Commands that are safe to run without asking: lint, tests, build, format check, model generation</td></tr><tr><td>Denied</td><td>Reading secrets or local config files, and destructive commands such as forced pushes or hard resets</td></tr><tr><td>Hooks</td><td>Optional: run the formatter after Claude edits a file</td></tr><tr><td>Personal settings</td><td>Anything personal goes in <code>settings.local.json</code>, which is not committed</td></tr></tbody></table><ol start="4"><li>Create reusable skills in <code>.claude/skills/</code>, one folder per skill with a <code>SKILL.md</code> that has a name, a description of when to use it and the steps to follow. Create at least:</li></ol><table tabindex="0"><thead><tr><th>Skill</th><th>Business description</th></tr></thead><tbody><tr><td>New feature component</td><td>Creates a standalone OnPush component with signals, ng-aquila, translated texts in English and German, and a test</td></tr><tr><td>New API service</td><td>Creates the service for a BFF resource using only the generated models, with a test</td></tr><tr><td>Add translation</td><td>Adds a key to both language files in the right group and uses it in the template</td></tr><tr><td>Commit</td><td>Reviews the staged changes and writes a Conventional Commit message</td></tr></tbody></table><ol start="5"><li>Add the Angular CLI MCP server. It lets Claude use the Angular documentation, best practices and project information of your workspace. Share it with the team in <code>.mcp.json</code>:</li></ol><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>claude mcp add --scope project angular-cli -- npx -y @angular/cli mcp</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol start="6"><li>Add the Chrome DevTools MCP server. It lets Claude open the running app in Chrome, read the console and network, and take screenshots:</li></ol><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>claude mcp add --scope project chrome-devtools -- npx -y chrome-devtools-mcp@latest</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol start="7"><li>Check the setup in Claude Code with <code>/mcp</code> (both servers connected), <code>/memory</code> (<code>CLAUDE.md</code> loaded) and <code>/permissions</code> (your rules listed).</li><li>Try it:</li></ol><table tabindex="0"><thead><tr><th>Try</th><th>Expected</th></tr></thead><tbody><tr><td>Ask for a new standalone page with a translated title</td><td>It follows the rules of <code>CLAUDE.md</code> and uses your component skill</td></tr><tr><td>Ask a question about an Angular API</td><td>It consults the Angular MCP server</td></tr><tr><td>Start the app and ask Claude to open it, log in and report console errors</td><td>It uses the Chrome DevTools MCP server</td></tr><tr><td>Ask it to commit</td><td>It uses the commit skill and the hooks accept the message</td></tr></tbody></table><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><ul><li><code>CLAUDE.md</code>, <code>.claude/settings.json</code>, the skills and <code>.mcp.json</code> are committed; <code>settings.local.json</code> is not</li><li><code>/mcp</code> shows <code>angular-cli</code> and <code>chrome-devtools</code> as connected</li><li>A command from the allowed list runs without a prompt, a denied command is refused</li><li>Each skill is found by its description and produces code that passes lint and tests</li><li>A feature built with Claude passes the same checks as one written by hand</li></ul><p>Done when a new teammate who clones the repository gets the same rules, skills and MCP servers with no manual setup, and the checks above pass.</p>',21)])])}const m=t(o,[["render",r]]);export{p as __pageData,m as default};
